const ADMIN_EMAIL = 'milenahoyossss@gmail.com'; // recibe los avisos de casos escalados o sin cupo
const b = $json.body ?? $json;
const txt = (v, max) => String(v ?? '').trim().slice(0, max);
const d = {
  session_token: txt(b.session_token, 200),
  ticket_id: Number.parseInt(b.ticket_id, 10) || 0,
  direccion: txt(b.direccion, 300),
  telefono: txt(b.telefono ?? b.phone, 30),
  cuadrante: txt(b.cuadrante, 12),
  admin_email: ADMIN_EMAIL,
};
let error = '';
if (!d.ticket_id) error = 'Falta el número de ticket.';
else if (d.direccion.length < 5) error = 'Escribe la dirección completa de la visita.';
return [{ json: { ...d, error } }];

const req = $('Validar solicitud de escalamiento').first().json;
const t = $input.first().json;
const responder = (respuesta) => [{ json: { route: 'responder', respuesta: { ticket_id: req.ticket_id, ...respuesta } } }];
const fmt = (f) => new Date(f).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });

if (req.error) return responder({ success: false, status: 'invalid', message: req.error });
if (!t.usuario_id) return responder({ success: false, status: 'unauthorized', message: 'Tu sesión expiró. Inicia sesión nuevamente.' });
if (!t.ticket_id) return responder({ success: false, status: 'not_found', message: 'No encontramos ese ticket en tu cuenta.' });
if (t.estado === 'Agendado' && t.fecha_visita)
  return responder({ success: true, status: 'appointment_scheduled', message: `Tu visita ya está agendada para ${fmt(t.fecha_visita)}.` });
if (['Escalado nivel 2', 'Pendiente de asignación'].includes(t.estado))
  return responder({ success: true, status: 'escalated', message: 'Tu caso ya está en la cola del equipo técnico. Te contactaremos por correo.' });
if (!['Escalamiento pendiente', 'En diagnóstico', 'Pendiente'].includes(t.estado))
  return responder({ success: false, status: 'closed', message: `Este ticket está en estado "${t.estado}" y no se puede escalar.` });

const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
// Solo se analiza lo que escribió el cliente (no las respuestas de la IA, que mencionan "humo" como advertencia).
const s = norm(`${t.descripcion_problema} ${t.historial_usuario}`);
const peligro = /(humo|olor a quemado|quemad[oa]|bateria (hinchada|inflada)|chispa|riesgo electrico|descarga electrica|corto ?circuito)/.test(s);
const fisico = t.es_dano_fisico === true || peligro ||
  /(liquido|derram|se (me )?mojo|mojad[oa]|pantalla (rota|partida|quebrada)|golpe|se (me )?cayo|dano fisico)/.test(s);

// Zona: la que eligió el cliente; si no, se deduce de la dirección con las zonas administradas (tabla zonas).
const zonas = (t.zonas || []).map((z) => ({ nombre: z.nombre,
  palabras: String(z.palabras || '').split(',').map((p) => norm(p).trim()).filter(Boolean) }));
if (req.cuadrante && !zonas.some((z) => z.nombre === req.cuadrante))
  return responder({ success: false, status: 'invalid', message: 'Selecciona una zona de atención válida.' });
let cuadrante = req.cuadrante;
if (!cuadrante) {
  const dir = norm(req.direccion);
  const escapar = (p) => p.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  cuadrante = (zonas.find((z) => z.palabras.some((p) => new RegExp(`\\b${escapar(p)}\\b`).test(dir))) || {}).nombre || '';
}
// Prioridad: el daño físico la sube (Alta) y el peligro para la persona la vuelve Crítica.
const NOMBRES = { 4: 'Crítica', 3: 'Alta', 2: 'Media', 1: 'Baja' };
const actual = Number(t.puntaje_prioridad || 2);
const minimo = peligro ? 4 : (fisico ? 3 : 0);
const puntaje = Math.max(actual, minimo);
const prioridad = {
  prioridad: NOMBRES[puntaje], puntaje_prioridad: puntaje,
  motivo_prioridad: puntaje > actual ? (peligro ? 'Riesgo físico confirmado al escalar' : 'Daño físico confirmado al escalar')
                                     : (t.motivo_prioridad || 'Sin cambio'),
  horas_sla: { 4: 4, 3: 24, 2: 48, 1: 72 }[puntaje],
  // Antelación mínima para la visita: los casos urgentes toman los cupos más cercanos
  horas_min: { 4: 1, 3: 2, 2: 24, 1: 48 }[puntaje],
};
return [{ json: {
  ...t, ...req, ...prioridad, cuadrante,
  route: fisico ? 'visita' : 'nivel2',
  tipo_dano: fisico ? 'Hardware' : 'Software',
  impacto: peligro ? 'Alto' : (fisico ? 'Medio' : 'Bajo'),
  es_dano_fisico: fisico,
} }];

const base = $('Clasificar riesgo y cuadrante').first().json;
const s = $input.first().json;
if (!base.cuadrante) return [{ json: { ...base, agendado: false, razon: 'No se identificó la zona de la dirección' } }];
if (!s.tecnico_id) return [{ json: { ...base, agendado: false, razon: `Sin técnicos disponibles en la zona ${base.cuadrante} en los próximos 14 días` } }];
return [{ json: { ...base, tecnico_id: s.tecnico_id, tecnico_nombre: s.tecnico_nombre, tecnico_correo: s.tecnico_correo,
  inicio: new Date(s.inicio).toISOString(), agendado: true } }];

const x = $input.first().json;
const d = $('Preparar decisión de agenda').first().json;
if (!x.ticket_id) {
  return [{ json: { enviar: false, respuesta: { success: false, status: 'retry', ticket_id: d.ticket_id,
    message: 'Ese horario acaba de ocuparse. Envía el formulario de nuevo para buscar otro cupo.' } } }];
}
const fecha_local = new Date(x.fecha_visita).toLocaleString('es-CO', { timeZone: 'America/Bogota', dateStyle: 'full', timeStyle: 'short' });
return [{ json: { ...x, fecha_local, tecnico_nombre: d.tecnico_nombre, tecnico_correo: d.tecnico_correo, enviar: true,
  respuesta: { success: true, status: 'appointment_scheduled', ticket_id: x.ticket_id, fecha_visita: x.fecha_visita,
    tecnico_nombre: d.tecnico_nombre, cuadrante: x.cuadrante,
    message: `Visita técnica agendada para ${fecha_local} (hora Colombia) con ${d.tecnico_nombre}. Te enviamos la confirmación por correo.` } } }];
